enum class Weekday
{
    monday,
    tuesday,
    wednesday,
    thursday,
    friday,
    saturday,
    sunday,
};

bool isWeekend(Weekday day)
{
    return day == Weekday::saturday || day == Weekday::sunday;
}

unitTests:
TEST("weekend days") { CHECK(isWeekend(Weekday::saturday)); CHECK(isWeekend(Weekday::sunday)); }
TEST("working days") { CHECK(!isWeekend(Weekday::monday)); CHECK(!isWeekend(Weekday::wednesday)); CHECK(!isWeekend(Weekday::friday)); }
TEST("days are numbered from monday = 0") { CHECK_EQ(static_cast<int>(Weekday::monday), 0); CHECK_EQ(static_cast<int>(Weekday::tuesday), 1); CHECK_EQ(static_cast<int>(Weekday::thursday), 3); CHECK_EQ(static_cast<int>(Weekday::sunday), 6); }

